import { Table } from 'animal-island-ui';

interface Person {
    key: string;
    name: string;
    age: number;
    island: string;
    fruit: string;
    hobby: string;
}

const columns = [
    {
        title: '岛民',
        dataIndex: 'name',
        width: 120,
    },
    {
        title: '年龄',
        dataIndex: 'age',
        width: 80,
        align: 'center',
    },
    {
        title: '岛屿',
        dataIndex: 'island',
    },
    {
        title: '喜欢的水果',
        dataIndex: 'fruit',
    },
    {
        title: '爱好',
        dataIndex: 'hobby',
        render: (value) => (
            <span style={{
                padding: '4px 12px',
                background: '#e0f7f4',
                borderRadius: 20,
                color: '#129a8e',
            }}>
                {value}
            </span>
        ),
    },
];

